WITH filtered AS (SELECT id, order_id, product_id, unit_price, COALESCE(quantity, 0) AS quantity_filled, CAST(quantity AS STRING) AS quantity_str FROM order_items WHERE product_id IS NOT NULL) SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY quantity_filled DESC, id) AS row_seq, CUME_DIST() OVER (ORDER BY quantity_filled DESC) AS quantity_filled_cume_dist, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY product_id), 4) AS unit_price_share, ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY quantity_filled, id) AS seq_no, NTILE(4) OVER (PARTITION BY product_id, order_id ORDER BY quantity_filled, id) AS quantity_filled_bucket FROM filtered
